 function showAchievements(){openModal('achievements','Твои достижения',`<p class="muted">Отмечаем сохранённые действия. Здесь нет обязательных серий дней: пропуск не обнуляет путь. После удаления записей счётчики пересчитываются.</p><div class="achievement-grid">${achievementCards()}</div><div class="modal-buttons">${btn('Продолжить','modal-close','arrow','primary')}</div>`,true);}
 function motivationPanel(){if(!quote)return '';const list=achievementData(),count=list.filter(a=>a.unlocked).length;return `<div class="motivation-grid"><section class="card quote-card"><div class="card-head"><span class="eyebrow accent">Мысль для твоего ритма</span>${icon('leaf',21)}</div><blockquote id="daily-quote">${esc(quote.text)}</blockquote><div class="quote-bottom"><span id="quote-author">${esc(quote.author)}</span>${btn('Другая мысль','quote-next','refresh','ghost')}</div></section><section class="card achievement-summary"><div class="card-head"><div><h2>Твои маленькие победы</h2><p class="muted">По твоим сохранённым действиям</p></div>${icon('cup',23)}</div><strong class="achievement-count">${count}<small> / ${list.length}</small></strong><p>${count?'Продолжай собирать привычки в удобном темпе.':'Первая запись или занятие станет точкой отсчёта.'}</p>${btn('Открыть достижения','achievements','arrow','full')}</section></div>`;}
 function pauseSessionClock(){if(activeTrainingId&&activeStarted){const s=findSession(activeTrainingId);if(s&&s.status!=='done')s.activeSeconds=(s.activeSeconds||0)+Math.max(0,Math.min(86400,(Date.now()-activeStarted)/1000));}activeStarted=0;}
 function resumeSessionClock(id){if(activeTrainingId!==id){pauseSessionClock();stopTimer();activeTrainingId=id;}if(!activeStarted&&!document.hidden)activeStarted=Date.now();}
