 function foodResults(){const list=state.foods.filter(f=>(foodCategory==='all'||f.kind===foodCategory)&&[f.name,f.category].join(' ').toLocaleLowerCase('ru').includes(foodQuery.toLocaleLowerCase('ru')));return list.length?list.map(f=>`<button type="button" class="food-result" data-action="food-select" data-id="${attr(f.id)}"><span><strong>${esc(f.name)}</strong><small>Б ${f.p} · Ж ${f.f} · У ${f.c} / 100 г</small></span><span class="pill">${f.kcal} ккал ${icon('plus',12)}</span></button>`).join(''):empty('Продукт не найден','Добавь свой продукт в редакторе или попробуй другое название.','','true','search')}
