 function saveFood(){const f=state.foods.find(f=>f.id===selectedFood),grams=Number($('#food-grams')?.value),date=$('#entry-date')?.value;if(!f||!Number.isFinite(grams)||grams<=0||grams>5000)return formError('Укажи порцию от 0,1 до 5 000 г.');if(!date)return formError('Выбери дату записи.');const meal=$('#food-meal').value;state.diary.push({id:uid('food'),foodId:f.id,name:f.name,date,meal,grams,kcal:f.kcal,p:f.p,f:f.f,c:f.c});foodDate=date;save();closeModal();if(route!=='nutrition')go('nutrition');else render();toast('Запись добавлена в дневник.')}
